UPDATE transactions t JOIN appointments a ON t.appointment_id = a.id SET t.amount = 55000 WHERE a.doctor_id = 10 AND a.appointment_date >= '2026-02-01' AND t.status = 'pending' AND t.amount IN (10000, 50000) AND t.type = 'income_patient'; UPDATE appointments a SET a.cost = 55000 WHERE a.doctor_id = 10 AND a.appointment_date >= '2026-02-01' AND a.status NOT IN ('cancelled', 'deleted') AND (a.cost = 0 OR a.cost = 10000 OR a.cost = 50000) AND EXISTS (SELECT 1 FROM transactions t WHERE t.appointment_id = a.id AND t.amount = 55000 AND t.status = 'pending');
